// Hindley-Milner style type inference
function inferType(expr: Expr, env: TypeEnv): Type {
  switch (expr.kind) {
    case 'number': return IntType;
    case 'variable': return env.lookup(expr.name);
    case 'lambda': {
      const paramType = new TypeVar();
      const newEnv = env.extend(expr.param, paramType);
      const bodyType = inferType(expr.body, newEnv);
      return FunctionType(paramType, bodyType);
    }
    case 'apply': {
      const funcType = inferType(expr.func, env);
      const argType = inferType(expr.arg, env);
      const resultType = new TypeVar();
      unify(funcType, FunctionType(argType, resultType));
      return resultType;
    }
  }
}
